import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import { Card, Container, Row, Col, Form } from "react-bootstrap";
import "chartist/dist/chartist.min.css";

/* ================= STYLE ================= */
const themeStyle = `
  .chart-scroll {
    overflow-x: auto;
    overflow-y: hidden;
  }

  .history-header {
    background: linear-gradient(87deg, #5e72e4 0, #825ee4 100%);
    border-radius: 8px 8px 0 0;
    padding: 20px;
  }

  .history-header .card-title {
    color: white;
    margin: 0;
    font-weight: bold;
    font-size: 1.25rem;
  }

  .form-label {
    font-weight: 700;
    color: #5e72e4;
    text-transform: uppercase;
    font-size: 0.75rem;
    margin-bottom: 6px;
  }

  .card {
    border: none;
    box-shadow: 0 0 2rem rgba(136,152,170,.15);
    border-radius: .75rem;
  }
`;

/* ================= FILTER นาทีที่ > 20 ================= */
const filterOverThreshold = (labels, series, threshold = 20) => {
  const newLabels = [];
  const newSeries = [];

  labels.forEach((label, i) => {
    if (series[i] > threshold) {
      newLabels.push(label);
      newSeries.push(series[i]);
    }
  });

  return { labels: newLabels, series: [newSeries] };
};

const CAMERA_MAP = {
  CAM01: "วิศวะ",
  CAM02: "วิทยาศาสตร์",
  CAM03: "ศิลปศาสตร์",
  CAM04: "PKY",
};

function History() {
  const now = new Date();
  const currentYearBE = now.getFullYear() + 543;

  const [day, setDay] = useState(now.getDate().toString());
  const [month, setMonth] = useState(
    (now.getMonth() + 1).toString().padStart(2, "0")
  );
  const [yearBE, setYearBE] = useState(currentYearBE.toString());
  const [startTime, setStartTime] = useState("07:00");
  const [endTime, setEndTime] = useState("22:00");
  const [cameraId, setCameraId] = useState("CAM01");
  const [chartState, setChartState] = useState({ labels: [], series: [[]] });

  const days = Array.from({ length: 31 }, (_, i) => (i + 1).toString());
  const years = [currentYearBE.toString(), (currentYearBE - 1).toString()];
  const times = Array.from({ length: 16 }, (_, i) =>
    `${(7 + i).toString().padStart(2, "0")}:00`
  );

  /* ================= FETCH ================= */
  const handleSearch = async () => {
    const yearCE = parseInt(yearBE) - 543;
    const date = `${yearCE}-${month}-${day.padStart(2, "0")}`;

    try {
      const res = await fetch(
        `http://localhost:3001/api/history?cameraId=${cameraId}&date=${date}&startTime=${startTime}&endTime=${endTime}`
      );
      const result = await res.json();

      if (result?.labels && result?.series) {
        const filtered = filterOverThreshold(
          result.labels,
          result.series[0],
          20
        );
        setChartState(filtered);
      }
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    handleSearch();
  }, [day, month, yearBE, startTime, endTime, cameraId]);

  /* ================= CHART OPTION ================= */
  const barChartOptions = {
    height: "420px",
    axisX: {
      showGrid: false,
      offset: 90, // กันเวลาโดนตัด
      labelInterpolationFnc: (value) => value,
    },
    axisY: {
      onlyInteger: true,
      low: 0,
      offset: 40,
    },
    fullWidth: true,
    chartPadding: {
      bottom: 50,
    },
  };

  /* ================= DRAW ================= */
  const drawBarLabels = (data) => {
    // แท่งกราฟ
    if (data.type === "bar") {
      data.element.attr({
        style: "stroke:#f5365c;stroke-width:30px;",
      });

      data.group.elem("text", {
        x: data.x2,
        y: data.y2 - 15,
        style:
          "font-size:13px;fill:#f5365c;font-weight:bold;text-anchor:middle",
      }).text(data.value.y);
    }

    // เวลาแกน X
    if (data.type === "label" && data.axis.units.pos === "x") {
      data.element.attr({
        transform: `translate(${data.x}, ${data.y + 20}) rotate(-45)`,
        style: "text-anchor:end;font-size:12px;",
      });
    }
  };

  return (
    <Container fluid className="py-4">
      <style>{themeStyle}</style>

      {/* ===== FILTER ===== */}
      <Card>
        <Card.Header className="history-header">
          <Card.Title>ค้นหาข้อมูลย้อนหลัง</Card.Title>
        </Card.Header>
        <Card.Body>
          <Row className="g-3">
            <Col md="3">
              <Form.Label className="form-label">ป้าย</Form.Label>
              <Form.Select value={cameraId} onChange={(e) => setCameraId(e.target.value)}>
                {Object.keys(CAMERA_MAP).map((c) => (
                  <option key={c} value={c}>{CAMERA_MAP[c]}</option>
                ))}
              </Form.Select>
            </Col>

            <Col md="4">
              <Form.Label className="form-label">วันที่</Form.Label>
              <div className="d-flex gap-2">
                <Form.Select value={day} onChange={(e) => setDay(e.target.value)}>
                  {days.map((d) => <option key={d}>{d}</option>)}
                </Form.Select>
                <Form.Select value={month} onChange={(e) => setMonth(e.target.value)}>
                  {[...Array(12)].map((_, i) => (
                    <option key={i} value={(i + 1).toString().padStart(2, "0")}>
                      {i + 1}
                    </option>
                  ))}
                </Form.Select>
                <Form.Select value={yearBE} onChange={(e) => setYearBE(e.target.value)}>
                  {years.map((y) => <option key={y}>{y}</option>)}
                </Form.Select>
              </div>
            </Col>

            <Col md="5">
              <Form.Label className="form-label">ช่วงเวลา</Form.Label>
              <div className="d-flex gap-2">
                <Form.Select value={startTime} onChange={(e) => setStartTime(e.target.value)}>
                  {times.map((t) => <option key={t}>{t}</option>)}
                </Form.Select>
                <Form.Select value={endTime} onChange={(e) => setEndTime(e.target.value)}>
                  {times.map((t) => <option key={t}>{t}</option>)}
                </Form.Select>
              </div>
            </Col>
          </Row>
        </Card.Body>
      </Card>

      {/* ===== CHART ===== */}
      {chartState.labels.length > 0 && (
        <Card className="mt-4">
          <Card.Header className="bg-transparent border-0">
            <h6 className="text-danger">🔴 แสดงเฉพาะช่วงที่ผู้โดยสารมากกว่า 20 คน</h6>
            <h4>กราฟสถิติ : {CAMERA_MAP[cameraId]}</h4>
          </Card.Header>
          <Card.Body>
            <div className="chart-scroll">
              <div style={{ width: Math.max(chartState.labels.length * 70, 600) }}>
                <ChartistGraph
                  data={chartState}
                  type="Bar"
                  options={barChartOptions}
                  listener={{ draw: drawBarLabels }}
                />
              </div>
            </div>
          </Card.Body>
        </Card>
      )}
    </Container>
  );
}

export default History;
